/// Whether `T` is read typed: a record through its column, a tag as its default.
pub(crate) fn has_column<T: 'static>() -> bool {
    is::<T, s::Hits>()
        || is::<T, s::Mana>()
        || is::<T, s::Stamina>()
        || is::<T, s::PlayerData>()
        || is::<T, s::Serial>()
        || is::<T, s::Graphic>()
        || is::<T, s::Hue>()
        || is::<T, s::WorldPosition>()
        || is::<T, s::Notoriety>()
        || is::<T, s::EntityName>()
        || is::<T, s::Amount>()
        || is::<T, s::Node>()
        || is::<T, s::Text>()
        || is::<T, s::TextFont>()
        || is::<T, s::TextColor>()
        || is::<T, s::BackgroundColor>()
        || is::<T, s::BorderRadius>()
        || is::<T, s::ChildOf>()
        || is::<T, s::UiMovable>()
        || is::<T, s::UiNoWindowDrag>()
        || is::<T, s::GlobalZIndex>()
        || is::<T, s::Interaction>()
        || is::<T, s::AutoOpenedCorpse>()
        || is::<T, s::ContainedInto>()
        || is::<T, s::EquipmentSlotsDto>()
        || is::<T, s::Facing>()
        || is::<T, s::IsContainer>()
        || is::<T, s::Item>()
        || is::<T, s::Mobile>()
        || is::<T, s::ManualOpenedCorpse>()
        || is::<T, s::EntityPropertiesDto>()
        || is::<T, s::ServerFlags>()
        || is::<T, s::ContainerSlotPosition>()
        || is::<T, s::ContainerWindow>()
        || is::<T, s::ContainerGumpTagDto>()
        || is::<T, s::GridContainerWindow>()
        || is::<T, s::GridLootWindow>()
        || is::<T, s::HealthBarWindow>()
        || is::<T, s::ServerGumpDto>()
        || is::<T, s::VendorWindow>()
        || is::<T, s::Player>()
        || is::<T, s::StatLocks>()
        || is::<T, s::BorderColorDto>()
        || is::<T, s::UOButton>()
        || is::<T, s::ComputedNode>()
        || is::<T, s::ContainerItemUI>()
        || is::<T, s::UiContainsByBounds>()
        || is::<T, s::UiCustomDto>()
        || is::<T, s::EditableText>()
        || is::<T, s::UiHoverTint>()
        || is::<T, s::UiMovableNoDrag>()
        || is::<T, s::UiName>()
        || is::<T, s::UiNoBlur>()
        || is::<T, s::NoPickup>()
        || is::<T, s::UiNoRightClickClose>()
        || is::<T, s::OptionsWindow>()
        || is::<T, s::UiPopup>()
        || is::<T, s::UiResizable>()
        || is::<T, s::ScrollPosition>()
        || is::<T, s::UiScrollbar>()
        || is::<T, s::StatLockButton>()
        || is::<T, s::StatusBarWindow>()
        || is::<T, s::ModSupersedes>()
        || is::<T, s::TextHue>()
        || is::<T, s::TextInput>()
        || is::<T, s::TextSpans>()
        || is::<T, s::TextWrap>()
        || is::<T, s::UiTooltip>()
        || is::<T, s::TopBarDragHandle>()
        || is::<T, s::TopBarButton>()
        || is::<T, s::TopBarFull>()
        || is::<T, s::IsTopBar>()
}

