/// One typed insert, queued in a bundle's order.
#[doc(hidden)]
pub enum TypedInsert {
    Graphic(w::Graphic),
    Hue(w::Hue),
    WorldPosition(w::WorldPosition),
    Notoriety(w::Notoriety),
    Name(w::EntityName),
    Amount(w::Amount),
    Node(w::Node),
    Text(w::Text),
    TextFont(w::TextFont),
    TextColor(w::TextColor),
    BgColor(w::BackgroundColor),
    BorderRadius(w::BorderRadius),
    ChildOf(w::ChildOf),
    Movable,
    NoWindowDrag,
    GlobalZ(w::GlobalZIndex),
    Interaction(w::Interaction),
    Facing(w::Facing),
    SlotPosition(w::ContainerSlotPosition),
    Container(w::ContainerWindow),
    ContainerTag(w::ContainerGumpTag),
    GridContainer(w::GridContainerWindow),
    GridLoot(w::GridLootWindow),
    HealthBar(w::HealthBarWindow),
    Player,
    BorderColor(w::BorderColor),
    Button(w::UoButton),
    ContainerItem(w::ContainerItemUi),
    ContainsByBounds,
    Custom(w::UiCustom),
    EditableText(w::EditableText),
    HoverTint(w::UiHoverTint),
    MovableNoDrag,
    UiName(w::UiName),
    NoBlur,
    NoPickup,
    NoRightClickClose,
    OptionsWindow,
    Popup,
    Resizable(w::UiResizable),
    Scroll(w::ScrollPosition),
    Scrollbar(w::UiScrollbar),
    StatLockButton(w::StatLockButton),
    StatusbarWindow(w::StatusBarWindow),
    Supersedes(w::ModSupersedes),
    TextHue(w::TextHue),
    TextInput,
    TextSpans(w::TextSpans),
    TextWrap(w::TextWrap),
    Tooltip(w::UiTooltip),
    TopbarBg,
    TopbarButton,
    TopbarFull,
    TopbarRoot,
}

