impl TypedInsert {
    /// Queues the insert on `b`'s entity; the returned builder is the same entity's.
    pub(crate) fn apply(self, b: &c::EntityBuilder) -> c::EntityBuilder {
        match self {
            TypedInsert::Graphic(v) => b.graphic(v),
            TypedInsert::Hue(v) => b.hue(v),
            TypedInsert::WorldPosition(v) => b.world_position(v),
            TypedInsert::Notoriety(v) => b.notoriety(v),
            TypedInsert::Name(v) => b.name(&v),
            TypedInsert::Amount(v) => b.amount(v),
            TypedInsert::Node(v) => b.node(v),
            TypedInsert::Text(v) => b.text(&v),
            TypedInsert::TextFont(v) => b.text_font(v),
            TypedInsert::TextColor(v) => b.text_color(v),
            TypedInsert::BgColor(v) => b.bg_color(v),
            TypedInsert::BorderRadius(v) => b.border_radius(v),
            TypedInsert::ChildOf(v) => b.child_of(v),
            TypedInsert::Movable => b.movable(),
            TypedInsert::NoWindowDrag => b.no_window_drag(),
            TypedInsert::GlobalZ(v) => b.global_z(v),
            TypedInsert::Interaction(v) => b.interaction(v),
            TypedInsert::Facing(v) => b.facing(v),
            TypedInsert::SlotPosition(v) => b.slot_position(v),
            TypedInsert::Container(v) => b.container(v),
            TypedInsert::ContainerTag(v) => b.container_tag(v),
            TypedInsert::GridContainer(v) => b.grid_container(v),
            TypedInsert::GridLoot(v) => b.grid_loot(v),
            TypedInsert::HealthBar(v) => b.health_bar(v),
            TypedInsert::Player => b.player(),
            TypedInsert::BorderColor(v) => b.border_color(v),
            TypedInsert::Button(v) => b.button(v),
            TypedInsert::ContainerItem(v) => b.container_item(v),
            TypedInsert::ContainsByBounds => b.contains_by_bounds(),
            TypedInsert::Custom(v) => b.custom(v),
            TypedInsert::EditableText(v) => b.editable_text(v),
            TypedInsert::HoverTint(v) => b.hover_tint(v),
            TypedInsert::MovableNoDrag => b.movable_no_drag(),
            TypedInsert::UiName(v) => b.ui_name(&v),
            TypedInsert::NoBlur => b.no_blur(),
            TypedInsert::NoPickup => b.no_pickup(),
            TypedInsert::NoRightClickClose => b.no_right_click_close(),
            TypedInsert::OptionsWindow => b.options_window(),
            TypedInsert::Popup => b.popup(),
            TypedInsert::Resizable(v) => b.resizable(v),
            TypedInsert::Scroll(v) => b.scroll(v),
            TypedInsert::Scrollbar(v) => b.scrollbar(v),
            TypedInsert::StatLockButton(v) => b.stat_lock_button(v),
            TypedInsert::StatusbarWindow(v) => b.statusbar_window(v),
            TypedInsert::Supersedes(v) => b.supersedes(&v),
            TypedInsert::TextHue(v) => b.text_hue(v),
            TypedInsert::TextInput => b.text_input(),
            TypedInsert::TextSpans(v) => b.text_spans(&v),
            TypedInsert::TextWrap(v) => b.text_wrap(v),
            TypedInsert::Tooltip(v) => b.tooltip(&v),
            TypedInsert::TopbarBg => b.topbar_bg(),
            TypedInsert::TopbarButton => b.topbar_button(),
            TypedInsert::TopbarFull => b.topbar_full(),
            TypedInsert::TopbarRoot => b.topbar_root(),
        }
    }
}

/// The resource parameter's value, typed; outer `None` when `T` is read as JSON.
pub(crate) fn res_get<T: 'static>(r: &c::Res) -> Option<Option<T>> {
    if is::<T, s::MouseInputDto>() {
        return Some(c::get_mouse(r).map(|v| cast(s::MouseInputDto::from_wit(v))));
    }
    if is::<T, s::KeyboardInputDto>() {
        return Some(c::get_keyboard(r).map(|v| cast(s::KeyboardInputDto::from_wit(v))));
    }
    if is::<T, s::Time>() {
        return Some(c::get_time(r).map(|v| cast(s::Time::from_wit(v))));
    }
    if is::<T, s::GameContextDto>() {
        return Some(c::get_context(r).map(|v| cast(s::GameContextDto::from_wit(v))));
    }
    if is::<T, s::GameSettingsDto>() {
        return Some(c::get_settings(r).map(|v| cast(s::GameSettingsDto::from_wit(v))));
    }
    if is::<T, s::GameStateDto>() {
        return Some(c::get_state(r).map(|v| cast(s::GameStateDto::from_wit(v))));
    }
    if is::<T, s::ContainerPositionsDto>() {
        return Some(c::get_container_positions(r).map(|v| cast(s::ContainerPositionsDto::from_wit(v))));
    }
    if is::<T, s::HostHotkeysDto>() {
        return Some(c::get_host_hotkeys(r).map(|v| cast(s::HostHotkeysDto::from_wit(v))));
    }
    if is::<T, s::ModHotkeyBindingsDto>() {
        return Some(c::get_mod_hotkeys(r).map(|v| cast(s::ModHotkeyBindingsDto::from_wit(v))));
    }
    if is::<T, s::WorldSingleClickDto>() {
        return Some(c::get_world_single_click(r).map(|v| cast(s::WorldSingleClickDto::from_wit(v))));
    }
    if is::<T, s::ModOptionsSchemaDto>() {
        return Some(c::get_schema(r).map(|v| cast(s::ModOptionsSchemaDto::from_wit(v))));
    }
    if is::<T, s::PlayerBuffsDto>() {
        return Some(c::get_buffs(r).map(|v| cast(s::PlayerBuffsDto::from_wit(v))));
    }
    if is::<T, s::GrabbedItem>() {
        return Some(c::get_grabbed_item(r).map(|v| cast(s::GrabbedItem::from_wit(v))));
    }
    if is::<T, s::PlayerSkillsDto>() {
        return Some(c::get_skills(r).map(|v| cast(s::PlayerSkillsDto::from_wit(v))));
    }
    if is::<T, s::TargetingState>() {
        return Some(c::get_target_state(r).map(|v| cast(s::TargetingState::from_wit(v))));
    }
    if is::<T, s::UiPickDto>() {
        return Some(c::get_pick(r).map(|v| cast(s::UiPickDto::from_wit(v))));
    }
    if is::<T, s::UiSurfaceDto>() {
        return Some(c::get_surface(r).map(|v| cast(s::UiSurfaceDto::from_wit(v))));
    }
    if is::<T, s::TextCaretDto>() {
        return Some(c::get_text_caret(r).map(|v| cast(s::TextCaretDto::from_wit(v))));
    }
    if is::<T, s::TextCompletionStateDto>() {
        return Some(c::get_text_completion_state(r).map(|v| cast(s::TextCompletionStateDto::from_wit(v))));
    }
    None
}

/// Sends `v` typed; false when `T` is sent as JSON.
pub(crate) fn send<T: 'static>(cmds: &wit::Commands, v: &T) -> bool {
    if is::<T, s::ChatMessage>() {
        let rec: w::ChatMessage = cast_ref::<T, s::ChatMessage>(v).to_wit();
        c::send_message(cmds, &rec);
        return true;
    }
    if is::<T, s::PromptOpenedEvent>() {
        let rec: w::PromptOpenedEvent = cast_ref::<T, s::PromptOpenedEvent>(v).to_wit();
        c::send_prompt(cmds, &rec);
        return true;
    }
    if is::<T, s::ContainerClosedEvent>() {
        let rec: w::ContainerClosedEvent = cast_ref::<T, s::ContainerClosedEvent>(v).to_wit();
        c::send_container_closed(cmds, rec);
        return true;
    }
    if is::<T, s::ContainerOpenedEvent>() {
        let rec: w::ContainerOpenedEvent = cast_ref::<T, s::ContainerOpenedEvent>(v).to_wit();
        c::send_container_opened(cmds, rec);
        return true;
    }
    if is::<T, s::ContainerSlotEvent>() {
        let rec: w::ContainerSlotEvent = cast_ref::<T, s::ContainerSlotEvent>(v).to_wit();
        c::send_container_slot(cmds, rec);
        return true;
    }
    if is::<T, s::ContextMenuEvent>() {
        let rec: w::ContextMenuEvent = cast_ref::<T, s::ContextMenuEvent>(v).to_wit();
        c::send_context_menu(cmds, &rec);
        return true;
    }
    if is::<T, s::InputConsume>() {
        let rec: w::InputConsume = cast_ref::<T, s::InputConsume>(v).to_wit();
        c::send_consume(cmds, rec);
        return true;
    }
    if is::<T, s::ModHotkeyFired>() {
        let rec: w::ModHotkeyFired = cast_ref::<T, s::ModHotkeyFired>(v).to_wit();
        c::send_hotkey(cmds, &rec);
        return true;
    }
    if is::<T, s::ItemDropSent>() {
        let rec: w::ItemDropSent = cast_ref::<T, s::ItemDropSent>(v).to_wit();
        c::send_drop_sent(cmds, rec);
        return true;
    }
    if is::<T, s::ItemMoveResult>() {
        let rec: w::ItemMoveResult = cast_ref::<T, s::ItemMoveResult>(v).to_wit();
        c::send_move_result(cmds, rec);
        return true;
    }
    if is::<T, s::LocalTargetResultEvent>() {
        let rec: w::LocalTargetResultEvent = cast_ref::<T, s::LocalTargetResultEvent>(v).to_wit();
        c::send_local_result(cmds, rec);
        return true;
    }
    if is::<T, s::UiClick>() {
        c::send_click(cmds);
        return true;
    }
    if is::<T, s::UiHover>() {
        let rec: w::UiHover = cast_ref::<T, s::UiHover>(v).to_wit();
        c::send_hover(cmds, rec);
        return true;
    }
    if is::<T, s::UiRightClick>() {
        let rec: w::UiRightClick = cast_ref::<T, s::UiRightClick>(v).to_wit();
        c::send_right_click(cmds, rec);
        return true;
    }
    false
}

/// The events of an event-reader parameter, typed; `None` when `T` is read as JSON.
pub(crate) fn read<T: 'static>(e: &wit::Events) -> Option<Vec<T>> {
    if is::<T, s::ChatMessage>() {
        let v: Vec<s::ChatMessage> = c::read_message(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::PromptOpenedEvent>() {
        let v: Vec<s::PromptOpenedEvent> = c::read_prompt(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::ContainerClosedEvent>() {
        let v: Vec<s::ContainerClosedEvent> = c::read_container_closed(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::ContainerOpenedEvent>() {
        let v: Vec<s::ContainerOpenedEvent> = c::read_container_opened(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::ContainerSlotEvent>() {
        let v: Vec<s::ContainerSlotEvent> = c::read_container_slot(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::ContextMenuEvent>() {
        let v: Vec<s::ContextMenuEvent> = c::read_context_menu(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::InputConsume>() {
        let v: Vec<s::InputConsume> = c::read_consume(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::ModHotkeyFired>() {
        let v: Vec<s::ModHotkeyFired> = c::read_hotkey(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::ItemDropSent>() {
        let v: Vec<s::ItemDropSent> = c::read_drop_sent(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::ItemMoveResult>() {
        let v: Vec<s::ItemMoveResult> = c::read_move_result(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::LocalTargetResultEvent>() {
        let v: Vec<s::LocalTargetResultEvent> = c::read_local_result(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::UiClick>() {
        let v: Vec<s::UiClick> = (0..c::read_click(e)).map(|_| s::UiClick {}).collect();
        return Some(cast(v));
    }
    if is::<T, s::UiHover>() {
        let v: Vec<s::UiHover> = c::read_hover(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    if is::<T, s::UiRightClick>() {
        let v: Vec<s::UiRightClick> = c::read_right_click(e).into_iter().map(Conv::from_wit).collect();
        return Some(cast(v));
    }
    None
}

